use vstd::prelude::*;

verus! {
    /// meshgrid(x, y) produces two matrices x_mat, y_mat both of dimension
    /// (y.len() × x.len()), where each row of x_mat is a copy of x,
    /// and each row of y_mat is the corresponding y‐value repeated.
    fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (x_mat: Vec<Vec<f32>>, y_mat: Vec<Vec<f32>>)
        // no pre‐conditions on floats, we only reason about lengths and copies
        ensures
            // the number of rows equals y.len()
            x_mat.len() == y.len(),
            y_mat.len() == y.len(),

            // each row of x_mat has length x.len() and copies the elements of x
            forall |i: usize| i < y.len() ==> x_mat[i].len() == x.len(),
            forall |i: usize, j: usize|
                i < y.len() && j < x.len() ==>
                x_mat[i][j] == x[j],

            // each row of y_mat has length x.len() and all entries equal y[i]
            forall |i: usize| i < y.len() ==> y_mat[i].len() == x.len(),
            forall |i: usize, j: usize|
                i < y.len() && j < x.len() ==>
                y_mat[i][j] == y[i],
    {
        let nx = x.len();
        let ny = y.len();
        // we pre‐allocate capacity but start empty
        let mut x_mat: Vec<Vec<f32>> = Vec::with_capacity(ny);
        let mut y_mat: Vec<Vec<f32>> = Vec::with_capacity(ny);

        // rewrite the for‐loop as an indexed while‐loop so we can give invariants
        let mut idx: usize = 0;
        while idx < ny
            invariant
                // idx always in [0, ny]
                idx <= ny,

                // we've pushed exactly idx rows so far
                x_mat.len() == idx,
                y_mat.len() == idx,

                // and those idx rows satisfy our specification
                forall |i: usize| i < idx ==> x_mat[i].len() == nx,
                forall |i: usize, j: usize|
                    i < idx && j < nx ==>
                    x_mat[i][j] == x[j],

                forall |i: usize| i < idx ==> y_mat[i].len() == nx,
                forall |i: usize, j: usize|
                    i < idx && j < nx ==>
                    y_mat[i][j] == y[i],

            decreases ny - idx,
        {
            let yv: f32 = y[idx];
            x_mat.push(x.clone());
            // vec![yv; nx] builds a Vec<f32> of length nx all equal to yv
            y_mat.push(vec![yv; nx]);
            idx += 1;
        }

        // return the two filled matrices
        (x_mat, y_mat)
    }
}

